/**
 * Parse each filename, extract the connection_name,
 * and classify as 'retain' or 'prune' based on whether
 * the connection still exists in parat_bridge.
 *
 * File naming convention:
 *   {message_id}---{connection_name}---{original_filename}
 *
 * Files whose connection_name is not found in
 * parat_bridge.connections are marked for deletion.
 */
const file_list   = (msg.payload || "").toString().trim();
const connections  = global.get("parat_bridge.connections") || {};
const SEPARATOR    = "---";
const FILES_DIR    = "/data/bridge-files/files/";

if (!file_list) {
    msg.payload = "No files found in " + FILES_DIR;
    msg._prune_list = [];
    return msg;
}

const filenames    = file_list.split("\n").filter(f => f.length > 0);
const to_prune     = [];
const to_retain    = [];

filenames.forEach(filename => {
    const parts = filename.split(SEPARATOR);

    // Need at least 3 parts: message_id, connection_name, original_filename
    if (parts.length < 3) {
        node.warn("Cannot parse filename (unexpected format): " + filename);
        to_retain.push(filename); // Keep files we cannot classify
        return;
    }

    const connection_name = parts[1];

    if (connections[connection_name]) {
        to_retain.push(filename);
    } else {
        to_prune.push(filename);
    }
});

msg._prune_list  = to_prune;
msg._retain_count = to_retain.length;
msg._prune_count  = to_prune.length;

node.log("Prune check: " + to_prune.length + " to delete, "
       + to_retain.length + " to keep");

return msg;

/**
 * Build a shell command to delete all orphaned files.
 * If nothing to prune, skip the exec node.
 */
const FILES_DIR = "/data/bridge-files/files/";
const to_prune  = msg._prune_list || [];

if (to_prune.length === 0) {
    msg.payload = msg._prune_count + " files pruned, "
                + msg._retain_count + " files retained";
    delete msg._prune_list;
    return [null, msg];
}

// Build safe rm command — each filename is quoted to handle spaces
const safe_paths = to_prune.map(f =>
    '"' + FILES_DIR + f.replace(/"/g, '') + '"'
);
msg.payload = "rm -f " + safe_paths.join(" ");

return [msg, null];

/**
 * Build a human-readable summary of the pruning operation.
 */
const pruned   = msg._prune_count  || 0;
const retained = msg._retain_count || 0;

msg.payload = pruned + " files pruned, " + retained + " files retained";

if (pruned > 0) {
    node.log(msg.payload);
}

delete msg._prune_list;
delete msg._prune_count;
delete msg._retain_count;

return msg;
